"use strict";
import { DepositInputForm } from "components/Liquidity/DepositInputForm";
import { useUpdatedAmountsFromDependentAmount } from "components/Liquidity/hooks/useDependentAmountFallback";
import ConfirmCreatePositionModal from "pages/Pool/Positions/create/ConfirmCreatePositionModal";
import {
  useCreatePositionContext,
  useCreateTxContext,
  useDepositContext,
  usePriceRangeContext
} from "pages/Pool/Positions/create/CreatePositionContext";
import { CreatePositionModal } from "pages/Pool/Positions/create/CreatePositionModal";
import { useCallback, useState } from "react";
import { Trans, useTranslation } from "react-i18next";
import { PositionField } from "types/position";
import { Button, Flex, Text } from "ui/src";
import { WarningSeverity } from "uniswap/src/components/modals/WarningModal/types";
export const DepositStep = () => {
  const {
    derivedPositionInfo: { currencies }
  } = useCreatePositionContext();
  const { t } = useTranslation();
  const { derivedPriceRangeInfo } = usePriceRangeContext();
  const {
    depositState: { exactField },
    setDepositState,
    derivedDepositInfo: {
      formattedAmounts,
      currencyAmounts,
      currencyAmountsUSDValue,
      currencyBalances,
      error: inputError
    }
  } = useDepositContext();
  const { txInfo, error: dataFetchingError, dependentAmount } = useCreateTxContext();
  const { deposit0Disabled, deposit1Disabled, priceDifference } = derivedPriceRangeInfo;
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
  const [isConfirmModalOpen, setIsConfirmModalOpen] = useState(false);
  const handleUserInput = (field, newValue) => {
    setDepositState((prev) => ({
      exactField: field,
      exactAmounts: {
        ...prev.exactAmounts,
        [field]: newValue
      }
    }));
  };
  const handleOnSetMax = (field, amount) => {
    setDepositState((prev) => ({
      exactField: field,
      exactAmounts: {
        ...prev.exactAmounts,
        [field]: amount
      }
    }));
  };
  const handleReview = useCallback(() => {
    if (priceDifference?.warning === WarningSeverity.High) {
      setIsConfirmModalOpen(true);
      return;
    }
    setIsReviewModalOpen(true);
  }, [priceDifference?.warning]);
  const [token0, token1] = currencies;
  const { updatedFormattedAmounts, updatedUSDAmounts, updatedDeposit0Disabled, updatedDeposit1Disabled } = useUpdatedAmountsFromDependentAmount({
    token0,
    token1,
    dependentAmount,
    exactField,
    currencyAmounts,
    currencyAmountsUSDValue,
    formattedAmounts,
    deposit0Disabled,
    deposit1Disabled
  });
  if (!token0 || !token1) {
    return null;
  }
  const disabled = !!inputError || !txInfo?.txRequest;
  const requestLoading = Boolean(
    !dataFetchingError && !inputError && !txInfo?.txRequest && currencyAmounts?.TOKEN0 && currencyAmounts.TOKEN1
  );
  return <>
      <Flex gap={32}>
        <Flex gap="$spacing4">
          <Text variant="subheading1">
            <Trans i18nKey="common.depositTokens" />
          </Text>
          <Text variant="body3" color="$neutral2">
            <Trans i18nKey="position.deposit.description" />
          </Text>
          
          {
    /* Show warning for single-sided liquidity */
  }
          {(updatedDeposit0Disabled || updatedDeposit1Disabled) && <Flex
    backgroundColor="$surface2"
    borderRadius="$rounded12"
    p="$spacing12"
    gap="$spacing8"
    borderWidth="$spacing1"
    borderColor="$surface3"
    mt={"$spacing8"}
  >
              <Text variant="body3" color="$neutral2">
                ⚠️ <Trans i18nKey="position.singleSided.title" defaults="Single-sided liquidity" />
              </Text>
              <Text variant="body4" color="$neutral2">
                {updatedDeposit0Disabled ? <Trans
    i18nKey="position.singleSided.token0Disabled"
    defaults="At the current price, you can only deposit {{token}}. {{disabledToken}} deposits are not available for this price range."
    values={{
      token: token1?.symbol,
      disabledToken: token0?.symbol
    }}
  /> : <Trans
    i18nKey="position.singleSided.token1Disabled"
    defaults="At the current price, you can only deposit {{token}}. {{disabledToken}} deposits are not available for this price range."
    values={{
      token: token0?.symbol,
      disabledToken: token1?.symbol
    }}
  />}
              </Text>
            </Flex>}
        </Flex>
      </Flex>
      <DepositInputForm
    autofocus={false}
    token0={token0}
    token1={token1}
    formattedAmounts={updatedFormattedAmounts}
    currencyAmounts={currencyAmounts}
    currencyAmountsUSDValue={updatedUSDAmounts}
    currencyBalances={currencyBalances}
    onUserInput={handleUserInput}
    onSetMax={handleOnSetMax}
    deposit0Disabled={updatedDeposit0Disabled}
    deposit1Disabled={updatedDeposit1Disabled}
    amount0Loading={requestLoading && exactField === PositionField.TOKEN1}
    amount1Loading={requestLoading && exactField === PositionField.TOKEN0}
  />
      <Flex row>
        <Button
    size="large"
    variant="branded"
    onPress={handleReview}
    isDisabled={disabled}
    key="Position-Create-DepositButton"
    loading={requestLoading}
  >
          {inputError ? inputError : t("swap.button.review")}
        </Button>
      </Flex>
      <CreatePositionModal isOpen={isReviewModalOpen} onClose={() => setIsReviewModalOpen(false)} />
      {priceDifference?.warning === WarningSeverity.High && <ConfirmCreatePositionModal
    isOpen={isConfirmModalOpen}
    onClose={() => setIsConfirmModalOpen(false)}
    onContinue={() => {
      setIsConfirmModalOpen(false);
      setIsReviewModalOpen(true);
    }}
    priceDifference={priceDifference}
  />}
    </>;
};
